async function normalizedRecipe(){recipe.name=$('recipe-name').value;recipe.model=model.value;return (await api('/api/studio/validate',recipe)).recipe;}
async function saveProjectRecipe(){recipe=await normalizedRecipe();await api(root()+'/recipe',recipe);await refresh(false);draftHistory.reset(recipe,'已保存项目配方');renderRecipe();}
async function showPhoto(id,scroll=true,{navigation=true}={}){if(navigation){photoNavigationEpoch++;pictureIntent++;}const request=++detailRequest,requestedProject=chosen,previousPhoto=photoId,previousWorkflow=detail?.workflow?.id;photoId=id;const loaded=await api(root()+'/photos/'+id);if(request!==detailRequest||chosen!==requestedProject||photoId!==id)return;detail=loaded;const switched=previousPhoto!==id||previousWorkflow!==detail.workflow.id;const {photo,workflow:w}=detail;$('studio-photo-detail').hidden=false;$('detail-name').textContent=photo.name;$('detail-workflow').href='/workflows/?id='+w.id;const original=asset(photo.originalWorkflowId,photo.originalAsset);if($('detail-original').getAttribute('src')!==original)$('detail-original').src=original;if(switched){selectedPreview=null;retouchAgent.clearPreview();writeViewURL(null);}renderPicture();renderStepRows(w,id);$('photo-reference-saved').replaceChildren();for(const ref of w.steps[0].output.featureReferences||[]){const img=el('img');img.src=asset(w.id,ref.assetId);img.alt=ref.role+' · '+ref.title;img.title=img.alt;$('photo-reference-saved').append(img);}if(switched){referenceDraft=[];$('photo-reference-files').value='';$('photo-reference-roles').replaceChildren();mask.reset();const saved=w.steps[0].output.maskAsset;if(saved)await mask.loadEditingMask(asset(w.id,saved));}renderPhotos();renderStudioHistory();void renderPhotoVersions();sync();if(navigation){writeViewURL(currentPicture()?.kind==='current'?null:currentPicture()?.reference);revealCurrentPhoto();}if(scroll){shell.setView('edit');if(matchMedia('(max-width:1100px)').matches)$('studio-photo-detail').scrollIntoView({behavior:'smooth',block:'start'});}}
function downloadJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('new-project').onsubmit=event=>{event.preventDefault();resetWorkspaceImage();task(async()=>{const p=await api('/api/studio/projects',{name:$('project-name').value,recipe:recipes[0]});$('project-name').value='';await openProject(p.id);notice('项目已创建，导入照片后即可选择配方。');});};
