$('select-all').onclick=()=>selectPhotoScope('all');$('select-none').onclick=()=>selectPhotoScope('none');
$('recipe-choice').onchange=()=>{const item=recipes.find(p=>p.id===$('recipe-choice').value);if(item){recipe=copy(item);model.set(recipe.model);renderRecipe();captureRecipe('套用 '+item.name);notice('配方已放入编辑器，保存或应用后生效。');}};
$('add-stage').onclick=()=>task(async()=>{if(recipe.stages.length>=12)throw Error('最多 12 个步骤。');const type=$('add-type').value,stage={type,name:{retouch:'人物自然精修',upscale:'本机超分4K',local:'方向与清晰度',grade:'全局色彩'}[type],enabled:true,options:type==='upscale'?superresOptions():type==='retouch'?{operation:'portrait-polish',style:'natural',paintLevel:2}:type==='local'?{rotate:0,flipSpace:'output',ratio:'original',focusX:50,focusY:50,maxEdge:0,denoise:0,sharpen:0}:{settings:settings()}};recipe.stages.splice(-1,0,stage);renderRecipe();captureRecipe('添加 '+stage.name);});
$('save-project-recipe').onclick=()=>task(async()=>{await saveProjectRecipe();notice('项目默认配方已保存。已有照片保持原流程，可点击“应用到所选照片”建立新版本。');});
$('apply-recipe').onclick=()=>task(async()=>{if(!picked().length)throw Error('先选择照片。');recipe=await normalizedRecipe();await api(root()+'/apply',{recipe,photoIds:picked().map(p=>p.id),revision:project.revision});draftHistory.reset(recipe,'已应用配方');await refresh();notice('已为所选照片建立新版本，可整体撤销此次应用，旧产物保留。');});
$('save-shared-recipe').onclick=()=>task(async()=>{const saved=await api('/api/studio/recipes',await normalizedRecipe());recipes=(await api('/api/studio/recipes')).recipes;renderRecipe();notice('已存入配方库：'+saved.name);});
$('export-recipe').onclick=()=>task(async()=>{downloadJSON(await normalizedRecipe(),'厚涂小站-修图配方.json');notice('分享文件只含配方参数，不含照片或账号凭据。');});
$('import-recipe').onchange=()=>task(async()=>{const file=$('import-recipe').files[0];if(!file)return;if(file.size>1000000)throw Error('配方文件过大。');recipe=(await api('/api/studio/validate',JSON.parse(await file.text()))).recipe;model.set(recipe.model);renderRecipe();captureRecipe('导入配方');notice('配方已导入编辑器，检查后保存并应用。');});
for(const [id,mode]of [['run-semi','semi'],['run-auto','auto']])$(id).onclick=()=>task(async()=>{if(!picked().length)throw Error('请先勾选照片。');await api(root()+'/run',{mode,concurrency:Number($('batch-concurrency').value),continueOnError:$('continue-error').checked});await refresh();notice(mode==='semi'?'正在执行一个待处理步骤。':'正在处理各张照片已保存的流程，可逐张查看结果。');});
$('refresh-project').onclick=()=>task(async()=>{focusAfterTask={elementId:'refresh-project'};await refresh();notice('工作流状态已刷新，已有产物和当前预览保留。');});
$('pause-run').onclick=()=>task(async()=>{await api(root()+'/pause',{});await refresh();});
$('deliver-photos').onclick=()=>task(async()=>{const value=await api(root()+'/delivery',{});const a=el('a','下载 '+value.count+' 张成片 · '+(value.bytes/1048576).toFixed(1)+' MB');a.href=value.downloadUrl;$('delivery-result').replaceChildren(a);a.click();notice('成片包已准备：'+value.count+'张最终图片'+(value.skipped?'；'+value.skipped+'张尚未完成，未收入此包。':'。'));});
$('mask-save').onclick=()=>task(async()=>{if(!detail)throw Error('请先选择照片。');const editingMask=await mask.build();if(!editingMask)throw Error('请先分析主体或上传蒙版。');await api(root()+'/photos/'+photoId+'/mask',{mask:editingMask});await refresh();notice('主体保护蒙版已保存，净场可以继续。');});
$('backup-project').onclick=()=>task(async()=>{const value=await api(root()+'/backup',{});const a=el('a','下载项目备份');a.href=value.downloadUrl;$('delivery-result').replaceChildren(a);a.click();notice('项目备份已校验，不含登录凭据；它包含原图与历史，请妥善保管。');});
$('restore-project').onchange=()=>task(async()=>{const file=$('restore-project').files[0];if(!file)return;if(file.size>210*1024*1024)throw Error('备份文件请控制在 210 MB 内。');const value=await api('/api/studio/restore',JSON.parse(await file.text()));await openProject(value.id);notice('备份已恢复为新项目；旧项目保留，AI 不会自动运行。');});

$('photo-reference-files').onchange=()=>task(async()=>{const files=[...$('photo-reference-files').files];if(files.length>5)throw Error('最多5张功能参考图。');referenceDraft=[];$('photo-reference-roles').replaceChildren();for(const file of files){if(file.size>MAX_IMAGE_UPLOAD_BYTES&&!imageOrigin(file))throw Error('单张参考图最大支持100 MB。');const bitmap=await createImageBitmap(file),scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height)),c=document.createElement('canvas');c.width=Math.round(bitmap.width*scale);c.height=Math.round(bitmap.height*scale);c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();const ref={title:file.name,role:'any',image:c.toDataURL('image/jpeg',.9)};referenceDraft.push(ref);field($('photo-reference-roles'),file.name,'any',v=>ref.role=v,{options:[{label:'本功能通用',value:'any'},{label:'服装',value:'outfit'},{label:'动作',value:'pose'},{label:'配色',value:'palette'},{label:'元素',value:'element'},{label:'妆容',value:'makeup'},{label:'场景',value:'scene'},{label:'效果目标',value:'result-guide'},{label:'画风参考',value:'style'}]});}notice('参考图已准备，请保存本张参考池。');});
$('photo-references-save').onclick=()=>task(async()=>{if(!photoId)throw Error('请选择照片。');await api(root()+'/photos/'+photoId+'/references',{references:referenceDraft});await refresh();notice('功能参考池已保存，可从等待参考的步骤继续。');});
$('studio-theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('houtu-color-theme',document.documentElement.dataset.theme);}catch{}};
setInterval(async()=>{if(!chosen||busy||polling||!running())return;polling=true;try{await refresh();if(!running()){await listProjects();notice(project.queue.message);}}catch(error){notice(error.message,true);}finally{polling=false;}},1200);
await task(async()=>{recipes=(await api('/api/studio/recipes')).recipes;colorPresets=(await api('/api/color/presets')).presets||[];await listProjects();if(chosen){await openProject(chosen);if(params.get('photo')&&project.photos.some(p=>p.id===params.get('photo')))await showPhoto(params.get('photo'),false,{navigation:false});}});

$('recipe-stages').addEventListener('change',invalidateSync);$('recipe-name').addEventListener('input',invalidateSync);

function recipeDraft(){return recipe?{...copy(recipe),name:$('recipe-name').value,model:model.value}:null;}
function captureRecipe(label){if(!recipe||historyRestoring)return;if(draftHistory.push(recipeDraft(),label))historyDomain='recipe';renderStudioHistory();updateUndo();}
function restoreRecipeDraft(index){historyDomain='recipe';const value=draftHistory.move(index);if(!value)return;historyRestoring=true;try{recipe=value;model.set(recipe.model);renderRecipe();invalidateSync();renderStudioHistory();}finally{historyRestoring=false;updateUndo();}}
function updateUndo(){const undo=$('studio-undo'),redo=$('studio-redo');if(!undo)return;const h=project?.history||{entries:[],cursor:0},locked=busy||maskBusy||running(),draft=historyDomain==='recipe';undo.disabled=locked||!project||!(draft&&draftHistory.canUndo||h.cursor>0);redo.disabled=locked||!project||!(draft&&draftHistory.canRedo||h.cursor<h.entries.length);undo.title=draft&&draftHistory.canUndo?'撤销配方草稿 · Ctrl+Z':'撤销项目操作 · Ctrl+Z';redo.title='重做 · Ctrl+Shift+Z / Ctrl+Y';}
async function projectHistory(direction,cursor){historyDomain='project';const oldDefault=JSON.stringify(project.recipe),draft=recipeDraft(),dirty=JSON.stringify(draft)!==oldDefault;await api(root()+'/history',{direction,cursor,revision:project.revision});await refresh();if(!dirty&&oldDefault!==JSON.stringify(project.recipe)){recipe=copy(project.recipe);model.set(recipe.model);draftHistory.reset(recipe,'恢复项目配方');renderRecipe();}invalidateSync();renderStudioHistory();notice('已恢复历史，原图与已有结果保留，未调用AI。');}
function undoStudio(){if(historyDomain==='recipe'&&draftHistory.canUndo){restoreRecipeDraft(draftHistory.cursor-1);return;}return task(()=>projectHistory('undo'));}
function redoStudio(){if(historyDomain==='recipe'&&draftHistory.canRedo){restoreRecipeDraft(draftHistory.cursor+1);return;}return task(()=>projectHistory('redo'));}
function renderStudioHistory(){if(!$('studio-project-history'))return;const locked=busy||maskBusy||running();historyList($('studio-recipe-history'),draftHistory.entries,draftHistory.cursor,{disabled:locked,onSelect:restoreRecipeDraft});const h=project?.history||{entries:[],cursor:0};historyList($('studio-project-history'),[{label:'记录开始'},...h.entries.map(e=>({label:new Date(e.at).toLocaleTimeString()+' · '+e.label}))],h.cursor,{disabled:locked||!project,onSelect:cursor=>task(()=>projectHistory('jump',cursor))});}
async function renderPhotoVersions(){if(!photoId){$('studio-version-history').replaceChildren();photoVersionRenderKey='';return;}const request=++versionsRequest,requested=photoId,requestedProject=chosen,workflowId=detail?.workflow?.id;try{const data=await api(root()+'/photos/'+requested+'/versions');if(request!==versionsRequest||photoId!==requested||chosen!==requestedProject||detail?.workflow?.id!==workflowId)return;const key=chosen+':'+requested+':'+JSON.stringify(data.versions);if(key===photoVersionRenderKey)return;photoVersionRenderKey=key;historyList($('studio-version-history'),data.versions.map((v,i)=>({label:(v.current?'当前版本 · 第':'恢复此版本 · 第')+(i+1)+'版 · '+v.name+' · '+v.done+'/'+v.total+'步'})),data.versions.findIndex(v=>v.current),{disabled:busy||running(),onSelect:index=>task(async()=>{if(photoId!==requested||chosen!==requestedProject)return;await api(root()+'/photos/'+requested+'/checkout',{workflowId:data.versions[index].id,revision:project.revision});await refresh();notice('已恢复此照片的保存版本，未生成新图片。');})});for(const [index,button]of [...$('studio-version-history').querySelectorAll('.edit-history-entry')].entries()){const version=data.versions[index],row=el('div',undefined,'studio-version-row'),preview=el('button','预览');preview.type='button';preview.dataset.readOnlyPreview='true';preview.dataset.unavailable=String(!version.picture);preview.disabled=busy||maskBusy||!version.picture;preview.setAttribute('aria-label','预览第'+(index+1)+'版');preview.onclick=()=>{if(photoId!==requested||chosen!==requestedProject||!version.picture)return;previewPicture(version.picture,'历史 · 第'+(index+1)+'版','history');shell.setView('edit');};button.replaceWith(row);row.append(button,preview);}}catch(e){notice(e.message,true);}}
$('recipe-name').addEventListener('change',()=>captureRecipe('修改配方名称'));
bindHistoryShortcuts({undo:undoStudio,redo:redoStudio,canUndo:()=>!$('studio-undo').disabled,canRedo:()=>!$('studio-redo').disabled,blocked:()=>busy||maskBusy||running()||!project});

const openWorkspaceProject=async(value,{isCurrent=()=>true}={})=>{const created=await api('/api/studio/projects',{name:'接续 · '+value.name,recipe:{stages:[{type:'export',name:'成片保存',options:{format:'png'}}]}});if(!isCurrent())return;await api('/api/studio/projects/'+created.id+'/photos?name='+encodeURIComponent(value.name),{source:value.origin||{kind:'workflow',workflowId:value.workflowId,assetId:value.assetId}});if(!isCurrent())return;await openProject(created.id);notice('已接续当前图片。原工作流保留；应用配方或开始流程前不会调用AI。');};
async function restoreStudioPicture(ref){if(!detail||!ref||!/^([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})$/.test(ref.workflowId||''))return false;const stamp=pictureIntent,owner=photoId,projectId=chosen,base=detail.workflow.id;let workflow=detail.workflow;if(ref.workflowId!==workflow.id){workflow=await api('/api/workflows/'+ref.workflowId);if(detail.photo.versions.includes(workflow.id)){if(workflow.kind!=='pipeline'||workflow.projectId!==chosen)return false;}else if(workflow.kind!=='retouch-agent'||workflow.projectId!==chosen||workflow.photoId!==photoId||!detail.photo.versions.includes(workflow.parentPipelineId))return false;}if(stamp!==pictureIntent||owner!==photoId||projectId!==chosen||base!==detail.workflow.id)return false;const reference=stepPicture(workflow,ref.stepId,ref.attemptId);if(reference?.assetId!==ref.assetId)return false;previewPicture(reference,'接续的步骤',workflow.kind==='retouch-agent'?'agent':workflow.id===detail.workflow.id?'step':'history',null,{restoring:true});return true;}
async function resumeStudioPicture(value){if(pictureIntent)return;if(!detail){await openWorkspaceProject(value);return;}const requested=viewReference(params);if(requested&&await restoreStudioPicture(requested))return;if(pictureIntent)return;const candidates=[value.resumeSources?.studio,value.origin||{workflowId:value.workflowId,assetId:value.assetId}].filter(ref=>ref?.assetId===value.assetId);for(const ref of candidates){if(await restoreStudioPicture(ref))return;if(pictureIntent)return;}if(defaultPicture()?.assetId!==value.assetId)await openWorkspaceProject(value);}
if(viewReference(params)&&!pictureIntent)try{await restoreStudioPicture(viewReference(params));}catch(error){notice('保存的预览暂时不可用：'+error.message,true);}
await registerWorkspaceEditor({tool:'studio',prepare:async()=>{if(busy||maskBusy)throw Error('照片项目仍在保存，请稍后切换。');if(!detail)return false;return handoffPicture(currentPicture());},open:openWorkspaceProject,resume:resumeStudioPicture});
